import { defineCollection } from "astro:content";
import { docsLoader } from "@astrojs/starlight/loaders";
import { docsSchema } from "@astrojs/starlight/schema";
import { glob } from "astro/loaders";
import { z } from "astro/zod";

const docs = defineCollection({
  loader: docsLoader(),
  schema: docsSchema(),
});

const blog = defineCollection({
  loader: glob({ pattern: "**/*.{md,mdx}", base: "./src/content/blog" }),
  schema: z.object({
    title: z.string(),
    description: z.string(),
    date: z.coerce.date(),
    author: z.string(),
    authorAvatar: z.string().optional(),
    authorUrl: z.string().optional(),
    tags: z.array(z.string()).default([]),
    cover: z.string().optional(),
    /** 1200×630 social card path (e.g. /og/blog/my-post.png). Falls back to cover, then site default. */
    ogImage: z.string().optional(),
    draft: z.boolean().default(false),
  }),
});

export const collections = { docs, blog };
import { Reveal } from "./chrome";

export function ThesisBand() {
	return (
		<div class="lp-thesis" data-lazy-art>
			<Reveal class="lp-thesis-in">
				<h2>
					Open-source framework for building{" "}
					<span class="lp-red">AI teammates</span>.
				</h2>
				<p class="lp-thesis-sub">
					You write the agent; Lobu handles everything under it — entities,
					identity, permissions, actions, and audit, in one system shared by
					every person and every agent in the company. Bring an agent you
					already run over MCP, or build one on the SDK. Either way, each
					sees what it is allowed to see, and nothing else.{" "}
					<a href="/compare/">See how it compares →</a>
				</p>
			</Reveal>
		</div>
	);
}

