/**
 * Animated "proxy for the source of truth" flow for the event-sourcing post:
 *
 *   sources keep the truth → connectors observe → the append-only log
 *   (supersede, never update) → governed reads with visibility compiled
 *   into the SQL → and every agent action lands back in the log.
 *
 * The log pane plays a supersede vignette on loop: churn.def v1 dims and
 * picks up a "superseded" tag as v2 fades in pointing at it. Pure CSS
 * keyframes, no hydration.
 */

const ACCENT = "var(--color-tg-accent)";

const SOURCES = ["slack", "gmail", "stripe", "postgres", "github"];

const TICKS = [
  "left-0 top-0 -translate-x-1/2 -translate-y-1/2",
  "right-0 top-0 translate-x-1/2 -translate-y-1/2",
  "left-0 bottom-0 -translate-x-1/2 translate-y-1/2",
  "right-0 bottom-0 translate-x-1/2 translate-y-1/2",
];

function CornerTicks() {
  return (
    <>
      {TICKS.map((pos) => (
        <span
          key={pos}
          aria-hidden="true"
          class={`absolute ${pos} font-mono text-[9px] leading-none`}
          style={{ color: "var(--color-page-text-muted)" }}
        >
          +
        </span>
      ))}
    </>
  );
}

function Card({
  step,
  title,
  sub,
  grow = 1,
  children,
}: {
  step: string;
  title: string;
  sub: string;
  grow?: number;
  children: preact.ComponentChildren;
}) {
  return (
    <div
      class="relative flex min-w-0 flex-col gap-1.5 border p-3.5"
      style={{
        flex: `${grow} 1 0%`,
        borderColor: "var(--color-page-border)",
        backgroundColor: "var(--color-page-bg)",
      }}
    >
      <div class="flex items-baseline gap-1.5">
        <span
          aria-hidden="true"
          class="shrink-0 font-mono text-[9.5px]"
          style={{ color: ACCENT }}
        >
          {step}
        </span>
        <span
          class="text-[12.5px] font-semibold leading-tight"
          style={{ color: "var(--color-page-text)" }}
        >
          {title}
        </span>
      </div>
      <span
        class="text-[10px] leading-snug"
        style={{ color: "var(--color-page-text-muted)" }}
      >
        {sub}
      </span>
      {children}
    </div>
  );
}

function Chip({ label, dim = false }: { label: string; dim?: boolean }) {
  return (
    <span
      class="border px-1.5 py-0.5 font-mono text-[9.5px]"
      style={{
        color: dim ? "var(--color-page-text-muted)" : ACCENT,
        borderColor: dim
          ? "var(--color-page-border)"
          : "var(--color-page-border-active)",
        backgroundColor: "var(--color-page-surface)",
      }}
    >
      {label}
    </span>
  );
}

function Connector() {
  return (
    <div
      class="relative hidden h-px flex-[0_0_22px] self-center sm:block"
      style={{ backgroundColor: "var(--color-page-border)" }}
    >
      <span
        class="tp-pip absolute top-1/2 h-1.5 w-1.5 -translate-y-1/2"
        style={{ backgroundColor: ACCENT }}
      />
    </div>
  );
}

function LogRow({
  id,
  kind,
  cls,
  tag,
}: {
  id: string;
  kind: string;
  cls?: string;
  tag?: string;
}) {
  return (
    <div class={`flex items-center justify-between gap-2 ${cls ?? ""}`}>
      <span class="flex min-w-0 items-center gap-1.5">
        <span style={{ color: "var(--color-page-text-muted)" }}>{id}</span>
        <span class="truncate" style={{ color: "var(--color-page-text)" }}>
          {kind}
        </span>
      </span>
      {tag ? (
        <span
          class={`shrink-0 border px-1 py-px text-[8px] ${
            cls === "tp-old" ? "tp-old-tag" : ""
          }`}
          style={{
            color: "var(--color-page-text-muted)",
            borderColor: "var(--color-page-border)",
          }}
        >
          {tag}
        </span>
      ) : null}
    </div>
  );
}

export function TruthProxyDiagram() {
  return (
    <div
      class="not-prose relative my-7 border p-4"
      style={{
        borderColor: "var(--color-page-border)",
        backgroundColor: "var(--color-page-surface-dim)",
      }}
    >
      <CornerTicks />
      <div
        class="mb-3 font-mono text-[10px] uppercase tracking-[0.22em]"
        style={{ color: "var(--color-page-text-muted)" }}
      >
        A proxy for the source of truth
      </div>
      <div class="flex flex-col gap-2.5 sm:flex-row sm:items-stretch sm:gap-0">
